insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-269","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Two reactions have similar $A$ factors. At a given temperature the slower one is the one with","options":["the higher activation energy","the lower activation energy","the larger $n$ in the Nernst equation","the smaller Faraday equivalent"],"answer_index":0,"explanation":"$k = A e^{-E_a/RT}$ falls exponentially as $E_a$ rises, so the higher barrier is slower if $A$ is comparable.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-270","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"From $k(300\\ \\mathrm{K}) = 1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$ and $k(310\\ \\mathrm{K}) = 2.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$, $k$ at 320 K is nearest","options":["$3.8 \\times 10^{-4}\\ \\mathrm{s^{-1}}$","$4.0 \\times 10^{-5}\\ \\mathrm{s^{-1}}$","$2.0 \\times 10^{-3}\\ \\mathrm{s^{-1}}$","$1.0 \\times 10^{-4}\\ \\mathrm{s^{-1}}$"],"answer_index":0,"explanation":"First $E_a$ from the 300/310 pair ($k$ doubles in 10 K, $E_a \\approx 53.6\\ \\mathrm{kJ\\ mol^{-1}}$), then $\\log(k_{320}/k_{300}) \\approx 0.58$, so $k_{320} \\approx 3.8 \\times 10^{-4}\\ \\mathrm{s^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"arrhenius-ea","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-271","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Increasing the concentration of a reactant that appears in the rate law generally","options":["increases the reaction rate","decreases $k$ at constant $T$","stops the reaction completely","changes $\\Delta H$ of the reaction"],"answer_index":0,"explanation":"Rate $= k[\\mathrm{A}]^x\\ldots$ grows with [A] whenever the order $x$ is positive.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-272","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Heating a reaction mixture of thermally activated molecules typically","options":["speeds the reaction because more molecules clear the energy barrier","always shifts the equilibrium constant to 1","lowers $E_a$ of an uncatalysed path","has no kinetic effect below 100 °C"],"answer_index":0,"explanation":"Temperature enters $k$ through the Arrhenius factor. Equilibrium may also shift, but that is a separate thermodynamic effect.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-273","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Adding a suitable catalyst to a reacting mixture","options":["increases the rate by opening a lower-energy path","is consumed as a stoichiometric reactant","alters the value of $\\Delta H$ for the net reaction","can change a first-order law into Faraday's law"],"answer_index":0,"explanation":"The catalyst is regenerated. It does not change the thermodynamics of the net reaction, only how fast equilibrium is reached.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-274","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a reaction between a solid and a gas or liquid, grinding the solid into a powder","options":["raises the rate by exposing a larger surface","lowers the rate because grains are smaller","changes the stoichiometric equation","removes the need for a collision"],"answer_index":0,"explanation":"Heterogeneous rates scale with the available surface. A powder offers far more area than a single lump of equal mass.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-275","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Ionic reactions in water are often much faster than reactions of covalent organic molecules because","options":["ions need little bond-breaking to meet, whereas covalent bonds must usually be broken and remade","ions have no charge","organic molecules never collide","water cannot solvate ions"],"answer_index":0,"explanation":"The nature of the reactants matters: many aqueous ion combinations are essentially encounter-controlled, unlike typical covalent substitutions.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-276","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Raising the pressure of a gaseous reactant (at fixed $T$) often increases the rate because","options":["the concentration of that gas rises, and rate laws depend on concentration","pressure changes the Faraday constant","gases become solids above 2 atm","molecularity becomes zero"],"answer_index":0,"explanation":"For an ideal gas, concentration $= p/RT$. A higher partial pressure therefore feeds the rate law.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-277","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Marble chips dissolve in acid more slowly than an equal mass of marble powder because the chips have","options":["a smaller surface area available for collision with H$^+$","a different chemical formula","zero activation energy","a larger $E^\\circ$ as a galvanic anode"],"answer_index":0,"explanation":"The heterogeneous rate is surface-limited. Powdering increases the area and therefore the observed rate.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-278","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A catalyst that accelerates both the forward and reverse steps equally will","options":["leave $\\Delta H$ and the equilibrium constant unchanged","make $\\Delta H$ more negative","shift $K$ toward products at every temperature","destroy the reverse reaction"],"answer_index":0,"explanation":"Equilibrium composition is fixed by $\\Delta G^\\circ$. The catalyst shortens the time needed to reach that same composition.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-279","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A photochemical reaction differs from an ordinary thermal reaction in that its rate","options":["depends on the intensity (and wavelength) of the absorbed light","is completely independent of photon energy","can never involve a chain of radicals","always follows Faraday's second law"],"answer_index":0,"explanation":"Absorption of a suitable photon supplies the activation; brighter light of the right colour produces more excited molecules per second.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-280","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A gas-phase reaction is first order in A. Doubling the partial pressure of A at constant $T$ and then raising $T$ so that $k$ also doubles will multiply the rate by","options":["4","2","1","8"],"answer_index":0,"explanation":"First-order rate $= k[\\mathrm{A}]$. Doubling [A] (via $p_A$) doubles the rate; doubling $k$ doubles it again, so the net factor is 4.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"rate-factors","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
    chapter_id text,
    subject_id text,
    stem text,
    options jsonb,
